using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.Json;using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.ApplicationServices;using AcApp=Autodesk.AutoCAD.ApplicationServices.Core.Application;
public class StampGraphics {
 const string Folder=@"C:\Users\user\Desktop\02_Справочники_CAD_Revit\odnolineyka\_Разработка\stamps";
 const string SourceDir=@"\\Server\DropBox\Работа server\4. Техдепартамент\4.1. Проекты\098 Ташкент-КТ\5 ПИР\5.5_Том 4 Пост охраны\01_ELF-D1-03-ЭОМ";
 static object Patch(Database db){var prior=HostApplicationServices.WorkingDatabase;HostApplicationServices.WorkingDatabase=db;try{
  var ids=new List<ObjectId>();var before=new List<object>();using(var tr=db.TransactionManager.StartTransaction()){var bt=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForRead);foreach(ObjectId id in bt){var b=(BlockTableRecord)tr.GetObject(id,OpenMode.ForRead);if(!b.IsFromExternalReference || !b.Name.Contains("ХБК_образец_"))continue;var path=Path.GetFullPath(Path.Combine(SourceDir,b.PathName));if(!File.Exists(path))throw new System.Exception("Missing referenced stamp: "+path);before.Add(new{Name=b.Name,Before=b.Cast<ObjectId>().Count(),Path=path});b.UpgradeOpen();b.PathName=path;ids.Add(id);}tr.Commit();}
  if(ids.Count>0){db.ResolveXrefs(false,false);db.ReloadXrefs(new ObjectIdCollection(ids.ToArray()));}
  var after=new List<object>();using(var tr=db.TransactionManager.StartTransaction()){foreach(var id in ids){var b=(BlockTableRecord)tr.GetObject(id,OpenMode.ForRead);int count=b.Cast<ObjectId>().Count();after.Add(new{Name=b.Name,After=count});if(count==0)throw new System.Exception("Stamp xref did not load: "+b.Name);}tr.Commit();}
  if(ids.Count>0)db.BindXrefs(new ObjectIdCollection(ids.ToArray()),false);
  return new{Before=before,After=after,Bound=true};
 }finally{HostApplicationServices.WorkingDatabase=prior;}}
 [CommandMethod("CODEXSTAMPGRAPHICSPREVIEW",CommandFlags.Session)]public void Preview(){try{var files=JsonSerializer.Deserialize<string[]>(File.ReadAllText(Path.Combine(Folder,"graphics_preview_files.json")));var result=new List<object>();foreach(var file in files){using(var db=new Database(false,true)){db.ReadDwgFile(file,FileOpenMode.OpenForReadAndAllShare,false,null);db.CloseInput(true);var patch=Patch(db);var output=Path.Combine(Folder,"GRAPHICS_"+Path.GetFileName(file));db.SaveAs(output,DwgVersion.Current);result.Add(new{File=output,Patch=patch});}}File.WriteAllText(Path.Combine(Folder,"graphics_preview.json"),JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true}));}catch(System.Exception ex){File.WriteAllText(Path.Combine(Folder,"graphics_preview_error.txt"),ex.ToString());}}
 [CommandMethod("CODEXSTAMPGRAPHICSAPPLY",CommandFlags.Session)]public void Apply(){var result=new List<object>();try{var files=JsonSerializer.Deserialize<string[]>(File.ReadAllText(Path.Combine(Folder,"verify_files.json")));foreach(var file in files){var doc=AcApp.DocumentManager.Cast<Document>().FirstOrDefault(d=>string.Equals(d.Name,file,StringComparison.OrdinalIgnoreCase));object patch;if(doc!=null){using(doc.LockDocument()){patch=Patch(doc.Database);((dynamic)doc.GetAcadDocument()).Save();doc.Editor.Regen();}}else{using(var db=new Database(false,true)){db.ReadDwgFile(file,FileOpenMode.OpenForReadAndAllShare,false,null);db.CloseInput(true);patch=Patch(db);db.SaveAs(file,DwgVersion.Current);}}result.Add(new{File=file,Patch=patch,Saved=true});File.WriteAllText(Path.Combine(Folder,"graphics_result.json"),JsonSerializer.Serialize(new{Complete=false,Files=result},new JsonSerializerOptions{WriteIndented=true}));}File.WriteAllText(Path.Combine(Folder,"graphics_result.json"),JsonSerializer.Serialize(new{Complete=true,Files=result},new JsonSerializerOptions{WriteIndented=true}));}catch(System.Exception ex){File.WriteAllText(Path.Combine(Folder,"graphics_apply_error.txt"),ex.ToString());}}
}